const ASSETS={"/index.html":{"text":"<!doctype html>\n<html lang=\"es\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#f3f4f8\"><meta name=\"description\" content=\"Pega una playlist pública de Spotify, busca sus canciones y guárdalas en YouTube Music.\"><title>Playlist Bridge</title><link rel=\"stylesheet\" href=\"style.css\"><script src=\"https://accounts.google.com/gsi/client\" async defer></script><script type=\"module\" src=\"app.js\"></script></head>\n<body><div class=\"app-shell\"><header><a class=\"brand\" href=\"./\">↗ <span>PLAYLIST BRIDGE</span></a><div class=\"connection\"><span id=\"googleState\" role=\"status\"></span><button id=\"connectGoogle\" class=\"secondary\">Conectar Google</button></div></header>\n<main><section class=\"import\"><h1>De Spotify a YouTube Music</h1><p class=\"intro\">Pega una playlist pública. Buscaremos sus canciones para guardarlas en tu biblioteca.</p><label class=\"sr-only\" for=\"playlistUrl\">Enlace de la playlist de Spotify</label><div class=\"input-action\"><input id=\"playlistUrl\" type=\"url\" aria-describedby=\"dailyLimit\" placeholder=\"https://open.spotify.com/playlist/…\"><button id=\"importSpotify\" class=\"primary\">Importar y buscar →</button></div><p id=\"dailyLimit\" class=\"daily-limit\"><strong>Límite: hasta 100 canciones buscadas al día.</strong> Cada intento de búsqueda cuenta.</p><p id=\"sourceNotice\" class=\"hint\" hidden></p></section>\n<div id=\"notice\" role=\"status\" aria-live=\"polite\" hidden></div><div id=\"rateWait\" class=\"rate-wait\" role=\"status\" hidden><span id=\"retryText\"></span><button id=\"stopWaiting\" class=\"quiet\">Detener espera</button></div>\n<div class=\"workspace\"><section id=\"reviewPanel\" class=\"review\" hidden><div class=\"section-head\"><div><h2 id=\"reviewTitle\">Canciones</h2><span id=\"trackBadge\" class=\"muted\">0 canciones</span></div><button id=\"searchAll\" class=\"quiet\" hidden>Buscar pendientes</button></div><label class=\"check select-all\"><input id=\"approveAll\" type=\"checkbox\"> Incluir todas las coincidencias</label><div id=\"trackList\" class=\"track-list\"></div></section>\n<aside id=\"destinationPanel\" class=\"destination\" hidden><h2>Guardar en YouTube Music</h2><label for=\"targetPlaylist\">Playlist de destino</label><select id=\"targetPlaylist\"><option value=\"new\">Crear una nueva (privada)</option></select><button id=\"refreshPlaylists\" class=\"quiet refresh\" disabled>↻ Actualizar playlists</button><div id=\"newPlaylistName\"><label for=\"playlistName\">Nombre</label><input id=\"playlistName\" value=\"Mi playlist de Spotify\" maxlength=\"150\"></div><button id=\"transfer\" class=\"primary save-button\" disabled>Crear playlist</button><div id=\"progressWrap\" hidden><progress id=\"progress\" max=\"1\" value=\"0\"></progress><p id=\"progressLabel\" class=\"hint\"></p></div><div id=\"result\" role=\"status\" aria-live=\"polite\" hidden></div><button id=\"changeDestination\" class=\"secondary\" hidden>Elegir otro destino</button></aside></div></main>\n<footer><button id=\"settingsButton\" class=\"quiet\">Ajustes</button><button id=\"reset\" class=\"quiet\">Borrar datos y desconectar</button></footer></div>\n<dialog id=\"settings\"><form method=\"dialog\"><div class=\"dialog-head\"><h2>Conexión de Google</h2><button class=\"quiet\" aria-label=\"Cerrar ajustes\">✕</button></div></form><p>Introduce el Client ID de tu proyecto de Google si esta instalación aún no tiene uno configurado.</p><label for=\"googleClient\">Google Client ID</label><input id=\"googleClient\" autocomplete=\"off\"><details><summary>Configuración del proyecto</summary><p>Habilita YouTube Data API v3 y autoriza este origen JavaScript:</p><code id=\"googleOrigin\"></code><p>Si el proyecto está en pruebas, añade tu cuenta como usuario de prueba.</p></details><button id=\"saveSettings\" class=\"primary\">Guardar ajustes</button><p class=\"hint\">Nunca pegues contraseñas ni Client Secrets.</p><p class=\"hint\"><a href=\"https://myaccount.google.com/permissions\" target=\"_blank\" rel=\"noopener noreferrer\">Revocar permisos de Google</a> · <a href=\"https://policies.google.com/privacy\" target=\"_blank\" rel=\"noopener noreferrer\">Privacidad de Google</a> · <a href=\"https://www.youtube.com/t/terms\" target=\"_blank\" rel=\"noopener noreferrer\">Condiciones de YouTube</a></p></dialog></body></html>","type":"text/html; charset=utf-8"},"/style.css":{"text":"@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&display=swap');\n:root{font-family:'DM Sans',sans-serif;color:#24212c;background:#f3f4f8;font-synthesis:none;--red:#ed3f4c;--line:#e9e7ef;--muted:#80758b}*{box-sizing:border-box}body{margin:0;padding:28px}button,input,select{font:inherit}button,a,input,select,summary{touch-action:manipulation}button{cursor:pointer}button:disabled{opacity:.4;cursor:not-allowed}a{color:inherit}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #f4a4ad;outline-offset:3px}.app-shell{max-width:1740px;margin:auto;background:#fff;border-radius:24px;border:1px solid #efedf4;box-shadow:0 20px 50px -40px #615876}header{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:26px 42px;border-bottom:1px solid #f0edf4}.brand{display:flex;align-items:center;gap:10px;font-size:28px;font-weight:500;text-decoration:none;color:var(--red)}.brand span{font-size:14px;font-weight:700;letter-spacing:1.1px}.connection{display:flex;align-items:center;gap:17px}#googleState{font-size:13px;color:#6f8072}main{padding:36px 42px 20px}.import{max-width:1100px}h1{font-size:clamp(28px,2.8vw,42px);font-weight:600;letter-spacing:-1.3px;line-height:1.2;margin:0 0 13px}.intro{font-size:16px;color:var(--muted);line-height:1.7;margin:0 0 25px}.input-action{display:flex;align-items:stretch;gap:12px}.input-action input{flex:1;min-width:0}input:not([type=checkbox]),select{width:100%;min-width:0;border:1px solid #ded9e8;border-radius:10px;padding:13px 15px;min-height:50px;font-size:16px;color:#45404f;background:#fff}input::placeholder{color:#a096ab}.primary,.secondary{border-radius:10px;min-height:46px;padding:12px 19px;font-size:14px;font-weight:600}.primary{border:1px solid #e53643;background:var(--red);color:#fff}.primary:hover:not(:disabled){background:#db3340}.secondary{border:1px solid #e5dfeb;background:#fff;color:#62566e}.secondary:hover:not(:disabled){background:#fff7f8;border-color:#f0bac2}.quiet{border:0;background:none;color:#8d7f98;font-size:13px;padding:7px 0}.quiet:hover:not(:disabled){color:var(--red)}.hint{font-size:12px;color:#90849b;line-height:1.8;margin:12px 0}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 365px;gap:40px;margin-top:31px;align-items:start}.review{min-width:0}.section-head{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:19px}.section-head>div{display:flex;align-items:baseline;gap:15px;min-width:0}h2{font-size:19px;font-weight:600;margin:0;letter-spacing:-.4px;overflow-wrap:anywhere}.muted{font-size:13px;color:#9a8da5;white-space:nowrap}.check{display:flex;align-items:center;gap:9px;font-size:13px;line-height:1.7;color:#84738f}.check input{accent-color:var(--red);width:17px;height:17px;margin:0;flex-shrink:0}.select-all{padding-bottom:17px;border-bottom:1px solid var(--line)}.track{display:grid;grid-template-columns:48px minmax(130px,1fr) minmax(175px,1.3fr) 36px;gap:15px;align-items:center;padding:19px 0;border-bottom:1px solid var(--line)}.track:last-child{border-bottom:0}.track>div{min-width:0}.number{position:relative;display:grid;place-items:center;width:42px;height:42px;background:#eee9f3;border-radius:9px;overflow:hidden}.number img{width:100%;height:100%;object-fit:cover}.track-note{color:#b5a3c2;font-size:24px}.track-index{position:absolute;bottom:0;right:0;background:#54415f99;color:white;font-size:8px;padding:2px 4px;border-radius:4px 0 0 0}.track strong{display:block;font-size:15px;font-weight:600;line-height:1.5;overflow-wrap:anywhere}.track small{display:block;font-size:12px;line-height:1.6;color:#95859f;margin-top:4px}.track select{font-size:13px;min-height:39px;padding:8px;border-radius:8px;border-color:#e9e3ef}.track a{display:inline-block;font-size:12px;line-height:1.6;color:#ae6572;text-decoration:none;margin-top:7px}.track a:hover{text-decoration:underline}.track .match-warning{color:#ba7a50}.manual-options{margin-top:7px}.manual-options summary{font-size:12px;color:#a091ab;cursor:pointer}.manual-options .track-search{display:block;margin-bottom:7px}.track .manual{font-size:13px;min-height:42px;padding:9px}.track .check{font-size:0;justify-content:center}.track .done{font-size:11px;color:#6a8c71}.destination{background:#f8f7fb;border:1px solid #eeebf3;border-radius:16px;padding:24px;min-width:0}.destination h2{font-size:18px;margin-bottom:23px}.destination label,dialog label{display:block;font-size:13px;color:#84718f;font-weight:500;margin-bottom:9px}.destination select,.destination input{font-size:14px;background:#fff}.refresh{display:block;font-size:12px;margin:8px 0 21px auto}.save-button{width:100%;margin-top:21px;font-size:15px;min-height:49px}#changeDestination{width:100%;font-size:13px;margin-top:12px;white-space:normal}.destination progress{width:100%;height:7px;accent-color:var(--red);margin-top:20px}#notice{background:#f6f3fa;border:1px solid #ebe2f1;color:#8f729e;border-radius:11px;padding:12px 16px;font-size:14px;line-height:1.75;margin:23px 0 0}#notice.error{background:#fff1f2;border-color:#f3d4db;color:#b66170}#result{font-size:13px;line-height:1.8;border-radius:9px;padding:13px;margin-top:17px;background:#edf6ef;color:#6e9078}#result.pending{background:#f0edf6;color:#8d789b}#result.failed{background:#fff0f2;color:#b15d6d}#result a{display:inline-block;font-size:12px;color:inherit;margin-top:8px}#result .hint{font-size:12px;color:inherit;opacity:.85}.transfer-error{font-size:13px;line-height:1.7;margin:10px 0}footer{display:flex;justify-content:space-between;align-items:center;padding:20px 42px 26px;border-top:1px solid #f2eff5;margin-top:10px}footer .quiet{font-size:12px;color:#a294ad}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}dialog{border:7px solid #fff;border-radius:21px;padding:25px;width:calc(100% - 28px);max-width:610px;max-height:90vh;overflow:auto;color:#403648;box-shadow:0 20px 70px #3f275c26}dialog::backdrop{background:#30223f66;backdrop-filter:blur(3px)}.dialog-head{display:flex;justify-content:space-between;align-items:center;gap:15px}.dialog-head h2{font-size:21px}.dialog-head button{font-size:18px}dialog p{font-size:14px;color:#8b7898;line-height:1.8}dialog details{margin:17px 0 22px}dialog summary{font-size:13px;color:#a4798c;cursor:pointer}dialog code{display:block;background:#f5f0f9;padding:10px;border-radius:7px;font-size:12px;overflow-wrap:anywhere}dialog .primary{width:100%}dialog .hint{font-size:11px}[hidden]{display:none!important}\n@media(min-width:1450px){header{padding:29px 50px}main{padding:42px 50px 24px}.workspace{grid-template-columns:minmax(0,1fr) 400px;gap:50px}.destination{padding:29px}.track{grid-template-columns:50px minmax(160px,1fr) minmax(230px,1.3fr) 40px;gap:19px}.track strong{font-size:16px}.track small{font-size:13px}.track select{font-size:14px}.track a,.manual-options summary{font-size:13px}.number{height:46px;width:46px}footer{padding-left:50px;padding-right:50px}}\n@media(max-width:1050px){body{padding:18px}.workspace{grid-template-columns:minmax(0,1fr) 305px;gap:26px}header{padding:23px 26px}main{padding:29px 26px 18px}.destination{padding:21px}.track{grid-template-columns:38px minmax(100px,1fr) minmax(130px,1.1fr) 28px;gap:10px}.number{width:34px;height:34px}.track strong{font-size:14px}.track select{font-size:12px}.section-head>div{flex-wrap:wrap;gap:7px 12px}footer{padding-left:26px;padding-right:26px}}\n@media(max-width:800px){.workspace{grid-template-columns:minmax(0,1fr);gap:28px}.destination{max-width:none}.track{grid-template-columns:43px minmax(120px,1fr) minmax(155px,1.2fr) 35px;gap:12px}.number{height:39px;width:39px}.track strong{font-size:15px}.track select{font-size:13px}.destination h2{font-size:19px}}\n@media(max-width:520px){body{padding:10px 7px}.app-shell{border-radius:18px}header{padding:19px 16px;gap:13px}.brand{font-size:25px;gap:6px}.brand span{font-size:10px;letter-spacing:.8px}.connection{gap:5px;flex-direction:column;align-items:flex-end}#googleState{font-size:10px}.connection .secondary{font-size:12px;min-height:39px;padding:9px 11px}main{padding:25px 16px 14px}h1{font-size:29px;letter-spacing:-.9px}.intro{font-size:14px;margin-bottom:20px}.input-action{flex-direction:column;gap:10px}.input-action input{font-size:16px;min-height:50px}.input-action .primary{min-height:48px;font-size:15px}.workspace{margin-top:25px}.section-head{align-items:flex-start;gap:10px}.section-head h2{font-size:18px}.section-head .quiet{font-size:12px;max-width:115px}.track{grid-template-columns:36px minmax(0,1fr) 30px;gap:9px;padding:16px 0;align-items:start}.number{width:32px;height:32px;grid-column:1;grid-row:1/3}.track>div:nth-child(2){grid-column:2;grid-row:1}.track>div:nth-child(3){grid-column:2;grid-row:2}.track>.check,.track>.done{grid-column:3;grid-row:1/3;align-self:center}.track strong{font-size:15px}.track small,.track select{font-size:12px}.track a,.manual-options summary{font-size:12px}.track .manual{font-size:14px}.destination{padding:21px 17px}.destination input,.destination select{font-size:16px}.destination label{font-size:13px}.check{font-size:12px}#notice{font-size:13px}.save-button{font-size:15px}footer{padding:17px 16px 22px;gap:16px}footer .quiet{font-size:11px}}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\n\n.rate-wait{display:flex;align-items:center;justify-content:space-between;gap:18px;border:1px solid #e5ddeb;border-radius:11px;background:#f6f3fa;color:#80658f;padding:14px 16px;font-size:14px;line-height:1.7;margin-top:17px}.rate-wait .quiet{flex-shrink:0;color:#9c4b61;text-decoration:underline}@media(max-width:520px){.rate-wait{font-size:13px;align-items:start;flex-direction:column;gap:5px}}\n\n.daily-limit{font-size:13px;line-height:1.7;color:#84748f;margin:13px 0 0}.daily-limit strong{font-weight:500;color:#62536d}@media(max-width:520px){.daily-limit{font-size:12px}}\n","type":"text/css; charset=utf-8"},"/app.js":{"text":"import{playlistId,videoId,deduplicate}from'./core.js';\nimport{searchRows}from'./matching.js';\nimport{transferSelected}from'./transfer.js';\nimport{createRateLimiter}from'./rate-limit.js';\nconst DEFAULT_GOOGLE_CLIENT='';\nconst $=id=>document.getElementById(id),key='playlistBridge.v1';let config=read('playlistBridge.config',{}),state=read(key,{rows:[],name:'Mi playlist de Spotify',destination:null}),googleAccess=null,busy=false,googleClient=null,googleTimer=null;config.google ||= DEFAULT_GOOGLE_CLIENT;\n\nlet rateWait=null;\nconst cooldownKey='playlistBridge.youtubeCooldown';\nconst requestLimiter=createRateLimiter({initialUntil:read(cooldownKey,0),onCooldown:until=>{try{if(until)localStorage.setItem(cooldownKey,JSON.stringify(until));else localStorage.removeItem(cooldownKey);}catch{}},onWait:info=>{rateWait=info;save();updateWait();},onResume:()=>{rateWait=null;updateWait();notice('Reanudando desde el punto donde se detuvo…');}});\nfunction updateWait(){const box=$('rateWait');box.hidden=!rateWait;if(!rateWait)return;const seconds=Math.max(0,Math.ceil((rateWait.until-Date.now())/1000));$('retryText').textContent='YouTube limita temporalmente las peticiones. Continuaremos automáticamente en '+seconds+' s. Reintento '+Math.max(1,rateWait.attempt)+' de '+rateWait.maxRetries+'.';}\n$('stopWaiting').onclick=()=>requestLimiter.cancel();\n\nfunction read(k,f){try{return JSON.parse(localStorage.getItem(k))||f;}catch{return f;}}\nfunction save(){state.name=$('playlistName').value;try{localStorage.setItem(key,JSON.stringify(state));}catch{notice('El navegador no permite guardar el progreso. Mantén esta página abierta hasta terminar.',true);}}\nfunction notice(message,error=false){$('notice').hidden=false;$('notice').classList.toggle('error',error);$('notice').textContent=message;}\nfunction decode(s){const el=document.createElement('textarea');el.innerHTML=s;return el.value;}\nfunction el(tag,text,cls){const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e;}\nfunction connected(){return !!googleAccess&&googleAccess.expires>Date.now();}\nfunction update(){\nconst n=state.rows.length,pending=state.rows.filter(row=>row.approved&&row.chosen&&!row.done),missing=state.rows.some(row=>!row.done&&!row.candidates?.length);\n$('reviewTitle').textContent=n?state.name:'Canciones';$('reviewPanel').hidden=!n;$('trackBadge').textContent=n+' canciones';$('destinationPanel').hidden=!n;\n$('searchAll').hidden=!n||!missing||!connected();$('searchAll').disabled=busy||!n;$('searchAll').textContent='Buscar pendientes';\n$('transfer').disabled=busy||!pending.length;$('transfer').textContent=!connected()?'Conectar para guardar':state.destination?'Continuar transferencia':state.targetPlaylist&&state.targetPlaylist!=='new'?'Añadir '+pending.length+' canciones':'Crear playlist';\n$('googleState').textContent=connected()?'Google conectado':'';$('connectGoogle').textContent=connected()?'Cambiar cuenta':'Conectar Google';\nfor(const id of['connectGoogle','importSpotify','reset','settingsButton','approveAll','changeDestination'])$(id).disabled=busy;\n$('playlistUrl').disabled=busy;$('playlistName').disabled=busy||!!state.destination;$('approveAll').checked=!!n&&state.rows.filter(row=>row.chosen&&!row.done).length>0&&state.rows.filter(row=>row.chosen&&!row.done).every(row=>row.approved);\n$('targetPlaylist').disabled=busy||!connected()||!!state.destination;$('refreshPlaylists').disabled=busy||!connected();$('newPlaylistName').hidden=!!state.targetPlaylist&&state.targetPlaylist!=='new';\n$('changeDestination').hidden=!state.destination;$('sourceNotice').hidden=!state.sourceWarning;$('sourceNotice').textContent=state.sourceWarning?'Comprueba que el número de canciones coincida con Spotify: su reproductor puede mostrar solo parte de la lista.':'';showResult();\n}\n\nfunction showResult(){\nconst r=$('result');r.replaceChildren();r.hidden=!state.destination&&!state.transfer?.error;if(r.hidden)return;\nconst done=state.rows.filter(row=>row.done).length,pending=state.rows.filter(row=>row.approved&&row.chosen&&!row.done).length,transfer=state.transfer;\nconst failed=transfer?.status==='failed',complete=transfer?.status==='complete';r.classList.toggle('failed',failed);r.classList.toggle('pending',!failed&&!complete);\nlet text=complete?done+' canciones confirmadas en el destino.':busy&&transfer?.status==='running'?'Transferencia en curso: '+done+' canciones confirmadas.':done?done+' canciones confirmadas; '+pending+' pendientes.':'Todavía no hay canciones confirmadas en el destino.';\nr.append(el('div',text));if(transfer?.error){r.append(el('p',transfer.error,'transfer-error'));r.append(el('p','Conservamos tus canciones y el progreso. Pulsa Continuar transferencia para reintentar, o elige otro destino.','hint'));}else if(!complete&&!busy)r.append(el('p','El destino está seleccionado, pero la transferencia no ha terminado. Pulsa Continuar transferencia.','hint'));\nif(state.destination)for(const[title,host]of[['Abrir en YouTube Music ↗','music.youtube.com']]){const a=el('a',title);a.href='https://'+host+'/playlist?list='+encodeURIComponent(state.destination);a.target='_blank';a.rel='noopener noreferrer';r.append(a);}\n}\n\nfunction render(){const list=$('trackList');list.replaceChildren();state.rows.forEach((row,i)=>{const line=el('div',null,'track');const art=el('span',null,'number');if(/^[\\w-]{11}$/.test(row.chosen||'')){const img=el('img');img.src='https://i.ytimg.com/vi/'+row.chosen+'/default.jpg';img.alt='';img.loading='lazy';art.append(img);}else art.append(el('span','♪','track-note'));art.append(el('span',String(i+1).padStart(2,'0'),'track-index'));line.append(art);const source=el('div');source.append(el('strong',row.title),el('small',row.artist));line.append(source);const match=el('div');if(row.candidates?.length){const select=el('select');select.setAttribute('aria-label',`Versión de ${row.title}`);select.disabled=busy||row.done;const none=el('option','Elige una versión');none.value='';select.append(none);for(const c of row.candidates){const option=el('option',c.title+' · '+c.channel);option.value=c.id;select.append(option);}select.value=row.chosen||'';select.onchange=()=>{row.chosen=select.value;row.approved=!!row.chosen;save();render();};match.append(select);if(row.chosen){const confidence=row.candidates.find(c=>c.id===row.chosen)?.score;if(confidence!=null&&confidence<.6)match.append(el('small','Revisa esta coincidencia','match-warning'));}}else match.append(el('small',row.searchStatus==='not-found'?'Sin coincidencias. Puedes buscar manualmente.':'Se buscará al conectar Google'));const search=el('a','Buscar otra versión ↗');search.href='https://music.youtube.com/search?q='+encodeURIComponent(row.artist+' '+row.title);search.target='_blank';search.rel='noopener noreferrer';search.className='track-search';if(row.chosen){const music=el('a','YouTube Music ↗');music.href='https://music.youtube.com/watch?v='+row.chosen;music.target='_blank';music.rel='noopener noreferrer';music.className='track-music';match.append(music);}\nif(!row.done){const manual=el('input');manual.className='manual';manual.placeholder='O pega el enlace de la versión correcta';manual.setAttribute('aria-label',`Enlace manual de ${row.title}`);manual.disabled=busy;manual.onchange=()=>{const id=videoId(manual.value.trim());if(!id)return notice('Introduce un enlace válido de YouTube.',true);row.candidates=[...(row.candidates||[]).filter(c=>c.id!==id),{id,title:'Versión elegida manualmente',channel:'YouTube'}];row.chosen=id;row.approved=true;save();render();};const options=el('details',null,'manual-options');options.append(el('summary','Cambiar versión'),search,manual);match.append(options);}line.append(match);if(row.done)line.append(el('span','✓ Añadida','done'));else{const label=el('label',null,'check');const check=el('input');check.type='checkbox';check.checked=!!row.approved;check.disabled=busy||!row.chosen;check.onchange=()=>{row.approved=check.checked;save();update();};label.append(check,document.createTextNode('Incluir'));line.append(label);}list.append(line);});update();}\nasync function run(fn){if(busy)return;busy=true;render();try{await fn();}catch(e){if(state.transfer?.status==='running'){state.transfer.status='failed';state.transfer.error=e.message||'No se pudo completar la transferencia.';}notice(e.message||'No se pudo completar la operación.',true);}finally{busy=false;save();render();}}\nasync function api(url,token,options={}){\nlet response;try{response=await fetch(url,{...options,headers:{Authorization:'Bearer '+token,...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});}catch{const error=Error('No se pudo confirmar la respuesta del servicio. Conservamos el progreso; comprueba tu conexión antes de reanudar.');error.uncertain=true;throw error;}\nlet data={};try{data=await response.json();}catch{if(response.ok){const error=Error('El servicio devolvió una respuesta incompleta. Comprueba tu biblioteca antes de reintentar.');error.uncertain=true;throw error;}}\nif(response.ok)return data;\nconst reason=data.error?.errors?.[0]?.reason||data.error?.details?.find(detail=>detail.reason)?.reason;\nconst error=Error(String(data.error?.message||'El servicio respondió con un error ('+response.status+').').replace(/<[^>]+>/g,''));error.status=response.status;error.reason=reason;\nif(response.status===401){googleAccess=null;error.message='La sesión de Google ha caducado. Vuelve a conectar y continúa desde el progreso guardado.';throw error;}\nif(['quotaExceeded','dailyLimitExceeded','dailyLimitExceededUnreg','QUOTA_EXCEEDED'].includes(reason)){error.quotaExceeded=true;error.message='Google ha agotado la cuota disponible. Una espera de 60 segundos no garantiza que se restablezca. El progreso está guardado: reanuda cuando vuelva a haber cuota.';throw error;}\nif(response.status===429||(response.status===403&&['rateLimitExceeded','userRateLimitExceeded','RATE_LIMIT_EXCEEDED'].includes(reason))){error.rateLimited=true;error.retryAfter=response.headers.get('Retry-After');error.message='YouTube limita temporalmente las peticiones. El progreso está guardado.';throw error;}\nif(reason==='accessNotConfigured'||reason==='serviceDisabled')error.message='Habilita YouTube Data API v3 en el proyecto de Google de tu Client ID y vuelve a intentarlo.';\nif(reason==='playlistNotFound')error.message='YouTube no encuentra la playlist de destino. Puedes reintentar o elegir otra playlist.';\nthrow error;\n}\nconst yt=(path,options)=>requestLimiter.run(()=>{if(!connected())throw Error('Vuelve a conectar Google para continuar desde el progreso guardado.');return api('https://www.googleapis.com/youtube/v3/'+path,googleAccess.token,options);});\n\nasync function loadPublicConfig(){if(config.google)return;try{const response=await fetch('/api/config');if(!response.ok)return;const data=await response.json();if(/^[\\w.-]+\\.apps\\.googleusercontent\\.com$/.test(data.googleClientId||''))config.google=data.googleClientId;}catch{}}\nfunction settings(){$('googleClient').value=config.google||'';$('googleOrigin').textContent=location.origin;$('settings').showModal();}\n$('settingsButton').onclick=settings;\n$('saveSettings').onclick=()=>{const id=$('googleClient').value.trim();if(!/^[\\w.-]+\\.apps\\.googleusercontent\\.com$/.test(id))return notice('Comprueba el Google Client ID.',true);if(config.google!==id)googleAccess=null;config={google:id};try{localStorage.setItem('playlistBridge.config',JSON.stringify(config));}catch{return notice('Activa el almacenamiento del navegador para guardar la configuración.',true);}$('settings').close();update();notice('Configuración guardada.');};\nfunction connectGoogle(){\nif(!config.google)return settings();if(!window.google?.accounts?.oauth2)return notice('No se ha cargado el acceso de Google. Comprueba tu conexión o el bloqueador de contenido y recarga.',true);\ngoogleClient=google.accounts.oauth2.initTokenClient({client_id:config.google,scope:'https://www.googleapis.com/auth/youtube.force-ssl',callback:r=>{\nclearTimeout(googleTimer);if(r.error)return notice('Google no ha concedido acceso: '+r.error,true);if(!google.accounts.oauth2.hasGrantedAllScopes(r,'https://www.googleapis.com/auth/youtube.force-ssl'))return notice('Concede el permiso de YouTube para buscar y guardar la playlist.',true);\ngoogleAccess={token:r.access_token,expires:Date.now()+Number(r.expires_in)*1000-30000};notice('Google conectado. Preparando tus playlists…');update();\nrun(async()=>{await loadTargets();if(state.rows.some(row=>!row.done&&!row.candidates?.length))await automaticSearch();else notice('Google conectado. Pega una playlist pública: sus canciones se buscarán automáticamente.');});\n},error_callback:()=>{clearTimeout(googleTimer);notice('La ventana de Google se cerró o no pudo abrirse. Si estás en el navegador integrado, abre esta app en Chrome o Edge y pulsa Conectar.',true);}});notice('Completa el acceso en la ventana de Google. Si no aparece, abre esta app en Chrome o Edge.');clearTimeout(googleTimer);googleTimer=setTimeout(()=>{if(!connected())notice('Google aún no ha confirmado el acceso. Si no ves su ventana, abre esta app en Chrome o Edge y vuelve a conectar.',true);},20000);googleClient.requestAccessToken({prompt:'select_account'});\n}\n$('connectGoogle').onclick=connectGoogle;\nasync function loadTargets(){\nconst select=$('targetPlaylist');select.replaceChildren();const fresh=el('option','Crear una playlist nueva (privada)');fresh.value='new';select.append(fresh);\ntry{let pageToken='';do{const data=await yt('playlists?'+new URLSearchParams({part:'snippet',mine:'true',maxResults:'50',...(pageToken?{pageToken}:{})}));for(const p of data.items||[]){const option=el('option',decode(p.snippet.title));option.value=p.id;select.append(option);}pageToken=data.nextPageToken||'';}while(pageToken);select.value=state.targetPlaylist||'new';if(!select.value){select.value='new';state.targetPlaylist='new';}}\ncatch(e){notice('No pudimos cargar tus playlists: '+e.message,true);if(e.rateLimited||e.quotaExceeded||e.cancelled)throw e;}update();\n}\n$('refreshPlaylists').onclick=()=>run(loadTargets);$('targetPlaylist').onchange=()=>{state.targetPlaylist=$('targetPlaylist').value;save();update();};\nasync function automaticSearch(){\nif(!connected()){notice(state.rows.length+' canciones importadas. Pulsa Conectar Google: se buscarán todas automáticamente al iniciar sesión.');return;}\nconst result=await searchRows(state.rows,yt,(row,done,total)=>{notice('Buscando en YouTube '+Math.min(done+1,total)+' de '+total+': '+row.artist+' — '+row.title);save();render();});\nstate.autoSearchPending=false;save();render();notice(result.found+' de '+result.total+' canciones con versión propuesta. Las coincidencias claras están incluidas; puedes cambiar la versión o excluir canciones antes de guardar.');\n}\nasync function afterImport(){state.autoSearchPending=true;save();await automaticSearch();}\n\nfunction replaceRows(rows,name){if(state.destination&& !confirm('La playlist ya creada seguirá en YouTube. ¿Quieres iniciar una nueva transferencia?'))return false;if(!rows.length)throw Error('No se han encontrado canciones.');const clean=deduplicate(rows);state={rows:clean.map(r=>({...r,candidates:[],chosen:'',approved:false,done:false})),name:name||'Mi playlist de Spotify',destination:null,targetPlaylist:'new'};$('targetPlaylist').value='new';$('playlistName').value=state.name;notice(`${clean.length} canciones importadas${rows.length>clean.length?`; ${rows.length-clean.length} repetidas omitidas`:''}. Conecta YouTube y busca sus versiones.`);save();render();return true;}\n$('importSpotify').onclick=()=>run(async()=>{\nconst id=playlistId($('playlistUrl').value);if(!id)throw Error('Pega un enlace completo de una playlist pública de Spotify.');\nlet response;try{response=await fetch('/api/spotify-playlist?id='+encodeURIComponent(id));}catch{throw Error('No se pudo consultar la lista pública. Comprueba tu conexión.');}\nconst data=await response.json();if(!response.ok)throw Error(data.error||'No se pudo leer la playlist pública.');if(!replaceRows(data.rows,data.name))return;state.sourceWarning=data.warning;save();render();await afterImport();\n});\n\n$('searchAll').onclick=()=>{if(!connected())return connectGoogle();return run(automaticSearch);};\n$('approveAll').onchange=()=>{for(const row of state.rows)if(row.chosen&&!row.done)row.approved=$('approveAll').checked;save();render();};$('playlistName').oninput=()=>{save();update();};\n$('changeDestination').onclick=()=>{\nif(!confirm('¿Elegir otra playlist de destino? Conservaremos las canciones seleccionadas. Las canciones ya guardadas seguirán en la playlist anterior.'))return;\nstate.destination=null;state.targetPlaylist='new';state.creating=false;state.transfer=null;for(const row of state.rows)row.done=false;$('targetPlaylist').value='new';$('progressWrap').hidden=true;save();render();notice('Elige otra playlist o crea una nueva. Conservamos las canciones y sus versiones.');\n};\n$('transfer').onclick=()=>{if(!connected())return connectGoogle();return run(async()=>{\nif((!state.targetPlaylist||state.targetPlaylist==='new')&&!state.name.trim())throw Error('Escribe un nombre para tu playlist.');\nconst selected=state.rows.filter(row=>row.approved&&row.chosen&&!row.done);if(!selected.length)throw Error('Incluye al menos una canción pendiente.');\nstate.transfer={status:'running',phase:'prepare',requested:selected.length,error:null};let fresh=false;save();\nif(state.creating&&!state.destination)throw Error('YouTube no confirmó si llegó a crear la playlist. Comprueba tu biblioteca y selecciona el destino existente antes de crear otra.');\nif(!state.destination&&state.targetPlaylist&&state.targetPlaylist!=='new'){state.destination=state.targetPlaylist;save();}\nif(!state.destination){\nstate.transfer.phase='create';state.creating=true;save();let data;\ntry{data=await yt('playlists?part=snippet,status',{method:'POST',body:JSON.stringify({snippet:{title:state.name.trim(),description:'Canciones seleccionadas con Playlist Bridge.'},status:{privacyStatus:'private'}})});}catch(e){if(!e.uncertain){state.creating=false;save();}throw e;}\nif(!data.id)throw Error('YouTube no confirmó el identificador de la playlist. Comprueba tu biblioteca antes de crear otra.');state.destination=data.id;state.creating=false;fresh=true;save();\n}\nstate.transfer.phase='check';$('progressWrap').hidden=false;$('progress').max=selected.length;$('progress').value=0;$('progressLabel').textContent='Comprobando el destino…';save();render();\nconst result=await transferSelected({yt,playlistId:state.destination,rows:selected,fresh,onProgress:progress=>{\nstate.transfer.phase='add';state.transfer.processed=progress.processed;$('progress').value=progress.processed;$('progressLabel').textContent=progress.processed+' de '+progress.total+' canciones confirmadas';save();render();\n}});\nstate.transfer={status:'complete',phase:'complete',...result,error:null};save();render();notice('Transferencia completada: '+result.added+' canciones añadidas y '+result.alreadyPresent+' que ya estaban en el destino.');\n});};\n\n$('reset').onclick=()=>{if(!confirm('¿Borrar configuración, sesiones y progreso de este navegador? Las playlists de YouTube se conservan.'))return;if(googleAccess&&window.google?.accounts?.oauth2)google.accounts.oauth2.revoke(googleAccess.token,()=>{});['playlistBridge.config',key].forEach(k=>localStorage.removeItem(k));['playlistBridge.spotify','playlistBridge.pkce'].forEach(k=>sessionStorage.removeItem(k));googleAccess=null;config={google:DEFAULT_GOOGLE_CLIENT};$('targetPlaylist').value='new';state={rows:[],name:'Mi playlist de Spotify',destination:null};$('playlistName').value=state.name;$('playlistUrl').value='';$('progressWrap').hidden=true;render();notice('Datos locales borrados y sesiones desconectadas.');};\n$('playlistName').value=state.name;render();void loadPublicConfig();setInterval(update,30000);setInterval(updateWait,1000);\n","type":"text/javascript; charset=utf-8"},"/core.js":{"text":"export function csvRows(text){const rows=[];let row=[],value='',quoted=false;const first=text.split(/\\r?\\n/)[0]||'';const delimiter=first.includes('\\t')?'\\t':(first.split(';').length>first.split(',').length?';':',');for(let i=0;i<text.length;i++){const c=text[i];if(c==='\"'){if(quoted&&text[i+1]==='\"'){value+='\"';i++;}else quoted=!quoted;}else if(!quoted&&c===delimiter){row.push(value);value='';}else if(!quoted&&(c==='\\n'||c==='\\r')){if(c==='\\r'&&text[i+1]==='\\n')i++;row.push(value);if(row.some(v=>v.trim()))rows.push(row);row=[];value='';}else value+=c;}if(quoted)throw Error('El CSV tiene comillas sin cerrar.');row.push(value);if(row.some(v=>v.trim()))rows.push(row);return rows;}\nexport function parseTracks(text){text=text.replace(/^\\uFEFF/,'').trim();if(!text)return[];const rows=csvRows(text);const header=rows[0].map(v=>v.trim().toLowerCase());const title=header.findIndex(v=>['track name','track','song','title','canción','cancion','nombre'].includes(v));const artist=header.findIndex(v=>['artist name(s)','artist name','artist','artists','artista'].includes(v));if(title>=0&&artist>=0)return rows.slice(1).map(r=>({title:(r[title]||'').trim(),artist:(r[artist]||'').trim()})).filter(r=>r.title&&r.artist);return text.split(/\\r?\\n/).filter(v=>v.trim()).map((line,i)=>{const parts=line.split(/\\s+[—–-]\\s+/);if(parts.length<2)throw Error(`Línea ${i+1}: usa artista — canción, con espacios alrededor del separador.`);return{artist:parts.shift().trim(),title:parts.join(' — ').trim()};}).filter(r=>r.title&&r.artist);}\nexport function playlistId(value){value=value.trim();if(/^[A-Za-z0-9]{22}$/.test(value))return value;const uri=value.match(/^spotify:playlist:([A-Za-z0-9]{22})$/);if(uri)return uri[1];try{const u=new URL(value);if(u.hostname!=='open.spotify.com')return null;return u.pathname.match(/\\/(?:playlist)\\/([A-Za-z0-9]{22})(?:\\/|$)/)?.[1]||null;}catch{return null;}}\nexport function videoId(value){if(/^[\\w-]{11}$/.test(value))return value;try{const u=new URL(value);if(u.hostname==='youtu.be')return /^[\\w-]{11}$/.test(u.pathname.slice(1))?u.pathname.slice(1):null;if(!['youtube.com','www.youtube.com','music.youtube.com','m.youtube.com'].includes(u.hostname))return null;const id=u.searchParams.get('v')||u.pathname.match(/^\\/(?:shorts|embed)\\/([\\w-]{11})/)?.[1];return /^[\\w-]{11}$/.test(id||'')?id:null;}catch{return null;}}\nexport function normalize(s){return s.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase().replace(/[^\\p{L}\\p{N}]+/gu,' ').trim();}\nexport function deduplicate(rows){const keys=new Set();return rows.filter(r=>{const k=normalize(r.artist)+'|'+normalize(r.title);if(keys.has(k))return false;keys.add(k);return true;});}\nexport function rank(title,artist,candidate){const words=normalize(title+' '+artist).split(' ').filter(w=>w.length>1);const hay=normalize(candidate.snippet.title+' '+candidate.snippet.channelTitle);return words.filter(w=>hay.includes(w)).length/Math.max(words.length,1)+( /official audio|topic/i.test(candidate.snippet.title+' '+candidate.snippet.channelTitle)?.12:0);}\n","type":"text/javascript; charset=utf-8"},"/matching.js":{"text":"import{normalize}from'./core.js';\nexport function durationSeconds(value){const m=/^PT(?:(\\d+)H)?(?:(\\d+)M)?(?:(\\d+)S)?$/.exec(value||'');return m?(+m[1]||0)*3600+(+m[2]||0)*60+(+m[3]||0):null;}\nexport function matchScore(row,candidate){\n  const title=normalize(candidate.title),channel=normalize(candidate.channel),all=title+' '+channel;\n  const coverage=(needle,hay)=>{const words=normalize(needle).split(' ').filter(w=>w.length>1);return words.length?words.filter(w=>hay.includes(w)).length/words.length:0;};\n  let score=.65*coverage(row.title,title)+.25*coverage(row.artist,all);\n  if(/official audio|topic|provided to youtube/i.test(candidate.channel+' '+candidate.title))score+=.06;\n  const original=normalize(row.title);for(const variant of['live','cover','remix','karaoke','sped up','slowed'])if(title.includes(variant)&&!original.includes(variant))score-=.28;\n  if(row.durationMs&&candidate.duration){const delta=Math.abs(row.durationMs/1000-candidate.duration);score+=delta<5?.08:delta>35?-.25:0;}\n  return Math.max(0,Math.min(1,score));\n}\nexport async function searchTrack(row,yt){\n  let items=row.searchItems||[];if(!items.length)for(const q of[`${row.artist} ${row.title}`,`${row.title} ${row.artist.split(',')[0]}`]){const data=await yt('search?'+new URLSearchParams({part:'snippet',type:'video',maxResults:'5',q}));items=(data.items||[]).filter(x=>/^[\\w-]{11}$/.test(x.id?.videoId||''));if(items.length){row.searchItems=items;break;}}\n  if(!items.length)return[];\n  const details=await yt('videos?'+new URLSearchParams({part:'contentDetails',id:items.map(x=>x.id.videoId).join(',')}));const durations=new Map((details.items||[]).map(x=>[x.id,durationSeconds(x.contentDetails?.duration)]));\n  delete row.searchItems;return items.map(x=>({id:x.id.videoId,title:x.snippet.title,channel:x.snippet.channelTitle,duration:durations.get(x.id.videoId)})).map(c=>({...c,score:matchScore(row,c)})).sort((a,b)=>b.score-a.score).slice(0,3);\n}\nexport async function searchRows(rows,yt,onProgress=()=>{}){\n  let processed=0;const pending=rows.filter(r=>!r.done&&!r.candidates?.length);for(const row of pending){onProgress(row,processed,pending.length);row.candidates=await searchTrack(row,yt);row.chosen=row.candidates[0]?.id||'';row.approved=!!row.chosen&&row.candidates[0].score>=.6;row.searchStatus=row.chosen?'found':'not-found';onProgress(row,++processed,pending.length);}\n  return{found:rows.filter(r=>r.chosen).length,total:rows.length};\n}\n","type":"text/javascript; charset=utf-8"},"/transfer.js":{"text":"export async function existingVideos(yt,playlistId,{fresh=false}={}){\n  // A playlist just returned by playlists.insert is empty; reading its items\n  // first is unnecessary and can fail before YouTube exposes the empty list.\n  if(fresh)return new Set();\n  const existing=new Set();let pageToken='';\n  try{do{const page=await yt('playlistItems?'+new URLSearchParams({part:'snippet',playlistId,maxResults:'50',...(pageToken?{pageToken}:{})}));for(const item of page.items||[])existing.add(item.snippet?.resourceId?.videoId);pageToken=page.nextPageToken||'';}while(pageToken);return existing;}\n  catch(error){\n    if(error.reason!=='playlistNotFound')throw error;\n    // Never interpret an arbitrary 404 as an empty list: verify the playlist\n    // itself with the same Google session and require a confirmed zero count.\n    const data=await yt('playlists?'+new URLSearchParams({part:'id,contentDetails',id:playlistId}));const playlist=(data.items||[]).find(p=>p.id===playlistId);\n    if(playlist&&playlist.contentDetails?.itemCount===0)return existing;\n    const message=playlist?'YouTube no permite leer todavía las canciones de esta playlist. Espera unos segundos y reintenta. No se ha añadido ninguna canción en este intento.':'YouTube no encuentra la playlist de destino en esta cuenta. Elige otro destino o vuelve a conectar la cuenta con la que la creaste.';\n    const failure=Error(message);failure.reason=playlist?'destinationNotReady':'destinationMissing';throw failure;\n  }\n}\nexport async function transferSelected({yt,playlistId,rows,fresh=false,onProgress=()=>{},wait=ms=>new Promise(resolve=>setTimeout(resolve,ms))}){\n  const existing=await existingVideos(yt,playlistId,{fresh});let added=0,alreadyPresent=0,processed=0;\n  for(const row of rows){\n    if(existing.has(row.chosen))alreadyPresent++;\n    else{\n      // A definitive 404 has not written anything. Retry that response only;\n      // unknown network outcomes must be reconciled before another insertion.\n      for(let attempt=0;;attempt++){\n        try{const result=await yt('playlistItems?part=snippet',{method:'POST',body:JSON.stringify({snippet:{playlistId,resourceId:{kind:'youtube#video',videoId:row.chosen}}})});if(!result.id){const error=Error('YouTube no confirmó que la canción se añadiera. El progreso está guardado: reintenta para comprobar el destino antes de continuar.');error.uncertain=true;throw error;}break;}\n        catch(error){if(error.reason==='playlistNotFound'&&fresh&&attempt<2){await wait(attempt===0?500:1500);continue;}if(error.reason==='playlistNotFound'){const failure=Error('YouTube no encuentra la playlist al añadir canciones. Puedes reintentar o elegir otro destino; tus canciones siguen guardadas.');failure.reason='destinationMissing';throw failure;}throw error;}\n      }\n      existing.add(row.chosen);added++;\n    }\n    row.done=true;onProgress({processed:++processed,total:rows.length,added,alreadyPresent,row});\n  }\n  return{processed,added,alreadyPresent};\n}\n","type":"text/javascript; charset=utf-8"},"/rate-limit.js":{"text":"export function retryDelay(value,{now=Date.now(),fallback=60000}={}){\n  if(value!=null&&String(value).trim()!==''){const seconds=Number(value);if(Number.isFinite(seconds))return seconds>=0?Math.ceil(seconds*1000):fallback;const date=Date.parse(value);if(Number.isFinite(date))return Math.max(0,date-now);}\n  return fallback;\n}\nfunction sleep(ms,signal){return new Promise((resolve,reject)=>{const abort=()=>{clearTimeout(timer);const error=Error('Espera detenida. El progreso está guardado; puedes reintentar más tarde.');error.cancelled=true;reject(error);};const timer=setTimeout(()=>{signal.removeEventListener('abort',abort);resolve();},ms);signal.addEventListener('abort',abort,{once:true});if(signal.aborted)abort();});}\nexport function createRateLimiter({now=Date.now,wait=sleep,minInterval=1000,maxRetries=3,initialUntil=0,onCooldown=()=>{},onWait=()=>{},onResume=()=>{}}={}){\n  let until=Number(initialUntil)||0,nextRequest=0,tail=Promise.resolve(),controller=null;\n  async function pause(target,kind,attempt){const remaining=target-now();if(remaining<=0)return;controller=new AbortController();if(kind==='cooldown')onWait({until:target,attempt,maxRetries});try{await wait(remaining,controller.signal);}finally{controller=null;if(kind==='cooldown')onResume();}}\n  function run(task){const promise=tail.then(async()=>{\n    for(let attempt=0;;attempt++){\n      await pause(until,'cooldown',attempt);await pause(nextRequest,'pace',attempt);nextRequest=now()+minInterval;\n      try{const result=await task();if(until){until=0;onCooldown(0);}return result;}\n      catch(error){if(!error.rateLimited||error.uncertain||error.quotaExceeded)throw error;\n        const fallback=60000*2**attempt,delay=retryDelay(error.retryAfter,{now:now(),fallback});until=Math.max(until,now()+Math.max(1000,delay));onCooldown(until);\n        if(attempt>=maxRetries){error.message='YouTube sigue limitando las peticiones después de varios intentos. El progreso está guardado. Reintenta más tarde; la app respetará la espera del servicio.';throw error;}\n      }\n    }\n  });tail=promise.catch(()=>{});return promise;}\n  return{run,cancel(){if(controller)controller.abort();},get until(){return until;}};\n}\n","type":"text/javascript; charset=utf-8"}};
// This service reads only Spotify's publicly accessible embed page. It never
// requests account cookies, access tokens, audio files or private Spotify APIs.
export function parseEmbed(html){
  const match=html.match(/<script\b(?=[^>]*\bid=["']__NEXT_DATA__["'])[^>]*>([\s\S]*?)<\/script>/i);
  if(!match)throw Error('Spotify no ha publicado los datos de esta lista en su reproductor. Inténtalo con otra playlist pública.');
  let entity;try{entity=JSON.parse(match[1]).props?.pageProps?.state?.data?.entity;}catch{throw Error('No se han podido leer los datos públicos de Spotify.');}
  if(entity?.type!=='playlist'||!Array.isArray(entity.trackList))throw Error('Esta playlist no está disponible en el reproductor público. Comprueba que sea pública.');
  const rows=entity.trackList.filter(t=>t.entityType==='track'&&/^spotify:track:[A-Za-z0-9]{22}$/.test(t.uri||'')&&t.title&&t.subtitle).map(t=>({title:String(t.title),artist:String(t.subtitle).replace(/\u00a0/g,' '),spotifyUri:t.uri,durationMs:Number(t.duration)||null}));
  if(!rows.length)throw Error('El reproductor público no muestra canciones de esta lista. Puede estar vacía, ser privada o tener restricciones.');
  return{name:String(entity.name||entity.title||'Playlist de Spotify'),rows,source:'public-embed',possiblyPartial:true,warning:rows.length>=100?'Se han leído 100 o más canciones. Spotify puede recortar el reproductor público: compara este total con la playlist original antes de transferir.':'Canciones leídas del reproductor público. Compara el total con Spotify: este método no garantiza que incluya toda la playlist.'};
}
export async function handlePlaylist(request,fetcher=(...args)=>globalThis.fetch(...args)){
  const url=new URL(request.url),id=url.searchParams.get('id');
  const json=(body,status=200)=>Response.json(body,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
  if(request.method!=='GET')return json({error:'Método no permitido.'},405);
  if(!/^[A-Za-z0-9]{22}$/.test(id||''))return json({error:'El identificador de la playlist no es válido.'},400);
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);
  try{
    const upstream=await fetcher(`https://open.spotify.com/embed/playlist/${id}`,{headers:{Accept:'text/html'},redirect:'manual',signal:controller.signal});
    if(!upstream.ok)return json({error:upstream.status===429?'Spotify limita temporalmente las consultas. Inténtalo más tarde.':'Spotify no permite leer esta playlist pública ahora. Inténtalo más tarde.'},upstream.status===429?429:502);
    const reader=upstream.body.getReader();let size=0,text='',decoder=new TextDecoder();try{for(;;){const{value,done}=await reader.read();if(done)break;size+=value.byteLength;if(size>4000000){await reader.cancel();return json({error:'La página de Spotify supera el tamaño que podemos procesar.'},502);}text+=decoder.decode(value,{stream:true});}text+=decoder.decode();}finally{reader.releaseLock();}
    return json(parseEmbed(text));
  }catch(e){console.error('Spotify public import:',e.name,e.message);return json({error:e.name==='TimeoutError'||e.name==='AbortError'?'Spotify ha tardado demasiado en responder. Inténtalo de nuevo.':e.message?.startsWith('Spotify')||e.message?.startsWith('Esta playlist')||e.message?.startsWith('El reproductor')||e.message?.startsWith('No se han')?e.message:'No se pudo consultar el reproductor público de Spotify. Inténtalo más tarde.'},502);}finally{clearTimeout(timer);}
}
export default{async fetch(request,env={}){const pathname=new URL(request.url).pathname;if(pathname==='/api/config'){if(request.method!=='GET')return new Response('Método no permitido',{status:405});const value=String(env.GOOGLE_CLIENT_ID||'');return Response.json({googleClientId:/^[\w.-]+\.apps\.googleusercontent\.com$/.test(value)?value:''},{headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});}if(pathname==='/api/spotify-playlist')return handlePlaylist(request);const asset=ASSETS[pathname==='/'?'/index.html':pathname];if(!asset)return new Response('No encontrado',{status:404});if(!['GET','HEAD'].includes(request.method))return new Response('Método no permitido',{status:405});return new Response(request.method==='HEAD'?null:asset.text,{headers:{'Content-Type':asset.type,'X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','Cache-Control':'no-cache'}});}};
